use vstd::prelude::*;

verus! {

fn append(a: &Vec<i32>, b: i32) -> (ret: Vec<i32>)
    ensures
        // The new vector has length one more than the input.
        ret.len() == a.len() + 1,
        // The first a.len() elements are exactly those of `a`.
        forall |k: usize| k < a.len() ==> ret.index(k) == a.index(k),
        // The last element is `b`.
        ret.index(a.len()) == b,
{
    let n = a.len();
    // Preallocate capacity for n+1 elements.
    let mut ret: Vec<i32> = Vec::with_capacity(n + 1);
    let mut i: usize = 0;
    // Copy each element from `a` into `ret`.
    while i < n
        invariant
            i <= n,
            // ret.len() tracks how many elements we've pushed so far.
            ret.len() == i,
            // All pushed elements match the corresponding elements of `a`.
            forall |k: usize| k < i ==> ret.index(k) == a.index(k),
        decreases n - i,
    {
        let v = a.index(i);
        ret.push(v);
        i += 1;
    }
    // Now we've copied all n elements; push the new element `b`.
    ret.push(b);
    ret
}

}

